{"results": [{"id": "hp_doc_53dd6d693ad9b1a315fb8cfbcd2d9e8336db167db1f8114fad56b0b14e5bdca5", "title": "Royal Wedding", "text": "Royal Wedding is a 1951 Metro-Goldwyn-Mayer musical comedy film starring Fred Astaire and Jane Powell, with music by Burton Lane and lyrics by Alan Jay Lerner. The film was directed by Stanley Donen; it was his second film and the first he directed on his own. It was released as Wedding Bells in the United Kingdom.", "score": 30.8747}, {"id": "hp_doc_c33ed7e4d4df3ab22bbb6a0f8ab904c19e47fb248ce951349b6318df5564d551", "title": "Mel Tormé Sings Fred Astaire", "text": "Mel Tormé Sings Fred Astaire is a 1956 album by Mel Tormé, recorded in tribute to Fred Astaire. This was Tormé's second recording with Marty Paich and his Dek-Tette.", "score": 20.9781}, {"id": "hp_doc_2b07f759b86db6e6ff98f6697ce4a1ddc5f7c25c88ee89ca9b3daa659732688b", "title": "Fred Astaire Dance Studios", "text": "Fred Astaire Dance Studios, Inc. is a ballroom dance franchise chain of studios in the United States and Canada, named after and co-founded by famous dancer Fred Astaire. It is headquartered in Longmeadow, Massachusetts, USA.", "score": 20.7194}], "remaining_searches": 2}
